node -e "const fs=require('fs');const h=fs.readFileSync('${1:-Index.html}','utf8');const a=require('acorn');let ok=1;[...h.matchAll(/<script(?![^>]*type=.module.)(?![^>]*src=)[^>]*>([\s\S]*?)<\/script>/g)].forEach((x,i)=>{try{a.parse(x[1],{ecmaVersion:2022})}catch(e){console.log('ERR',i,e.loc&&e.loc.line,e.message);ok=0}});[...h.matchAll(/<script[^>]*type=.module.[^>]*>([\s\S]*?)<\/script>/g)].forEach((x,i)=>{try{a.parse(x[1],{ecmaVersion:2022,sourceType:'module'})}catch(e){console.log('ERRm',i,e.message);ok=0}});console.log(ok?'SINTASSI OK':'ROTTO')"
